/** Additional, genuinely computed university tools. No eval, network calls, or external dependencies.
 * Every tool defines an explicit model and bounded/default input values. Outputs are computed locally.
 */
import {fmt,requireFinite,linspace,nums,mean,variance,pairs,linearFit} from './core.js';
const PI=Math.PI,ln=Math.log,exp=Math.exp,sqrt=Math.sqrt,abs=Math.abs,pow=Math.pow;
const n=(key,label,value,unit='')=>({key,label,type:'number',value:String(value),unit});
const txt=(key,label,value)=>({key,label,type:'textarea',value,rows:4});
const valid=(ok,msg)=>{if(!ok)throw Error(msg)};
const output=(label,value,unit='')=>[label,value,unit];
const logFact=n=>{let s=0;for(let i=2;i<=n;i++)s+=ln(i);return s};
const cdf=z=>{ // Abramowitz-Stegun 7.1.26 approximation, absolute error ~ 1.5e-7
 const a=abs(z)/sqrt(2),t=1/(1+.3275911*a),erf=1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*exp(-a*a);return .5*(1+(z<0?-erf:erf));
};
