export const departments=[
 ['physics','Physics'],['chemistry','Chemistry'],['mathematics','Mathematics'],['computer-science','Computer Science'],['statistics-probability','Statistics & Probability'],['biological-sciences','Biological Sciences'],['earth-space','Earth & Space Sciences'],['logic-systems','Logic & Systems Science'],['mechanical-engineering','Mechanical Engineering'],['electrical-engineering','Electrical & Electronics Engineering'],['civil-engineering','Civil Engineering'],['chemical-engineering','Chemical & Process Engineering'],['textile-engineering','Textile Engineering'],['electronics-communication','Electronics & Communication'],['aerospace-engineering','Aerospace & Aeronautical Engineering'],['biomedical-engineering','Biomedical Engineering'],['agricultural-engineering','Agricultural Engineering'],['marine-ocean','Marine & Ocean Sciences'],['basic-medical','Basic Medical Sciences'],['clinical-medicine','Clinical Medicine'],['dentistry','Dentistry & Oral Health'],['pharmacy','Pharmacy & Pharmaceutical Sciences'],['nursing','Nursing & Allied Health'],['veterinary','Veterinary Medicine'],['public-health','Public Health'],['food-nutrition','Food & Nutrition'],['economics','Economics'],['finance-accounting','Finance & Accounting'],['psychology','Psychology'],['geography','Geography'],['history','History'],['philosophy','Philosophy'],['business-management','Business & Management'],['agriculture-forestry','Agriculture & Forestry'],['law','Law'],['anthropology','Anthropology'],['archaeology','Archaeology'],['sociology','Sociology']
].map(([id,label])=>({id,label}));
export const expandedTools=[];
/** Each calculator has a domain-specific formula and editable inputs. Sweep graphs are computed from the same model. */
function add(id,title,category,department,description,fields,calculate,opts={}){
 const t={id,title,category,department,icon:opts.icon||'functions',subtitle:opts.subtitle||description,description,fields,
 compute(raw){const v={};for(const f of fields){if(f.type==='textarea'){v[f.key]=String(raw[f.key]??'');continue;}if(String(raw[f.key]??'').trim()==='')throw Error(`Enter ${f.label}.`);v[f.key]=Number(raw[f.key]);requireFinite(v[f.key]);if(f.min!==undefined)valid(v[f.key]>=f.min,`${f.label} must be at least ${f.min}.`);if(f.max!==undefined)valid(v[f.key]<=f.max,`${f.label} must not exceed ${f.max}.`);}const values=calculate(v);valid(Array.isArray(values)&&values.length>0,'No numerical outputs defined.');for(const item of values){valid(item.length>=2&&Number.isFinite(item[1]),`Undefined result (${item[0]}). Check the model domain and inputs.`);}
 const metrics=values.map(([label,value,unit])=>({label,value:fmt(value),unit:unit||''}));const method=opts.method||description;const notes=opts.notes||['An idealized educational model; check its assumptions before interpreting real-world measurements.','Units shown beside the input and output values are part of the model and must be respected.'];
 let chart;if(opts.sweep){const {key,metric=0,from,to,label}=opts.sweep,defaultValue=v[key];let start=from??(defaultValue===0?0:Math.max(0,defaultValue*.2)),end=to??(defaultValue===0?2:defaultValue*2);if(end<=start){start=0;end=1;}const points=[];for(const x of linspace(start,end,60)){try{const val=calculate({...v,[key]:x})[metric][1];if(Number.isFinite(val)&&abs(val)<1e18)points.push({x,y:val});}catch{ /* invalid points in parameter sweep are omitted */ }}if(points.length>1)chart={series:[{name:values[metric][0],points,color:'#087e80',type:'line'}],xLabel:label||fields.find(f=>f.key===key)?.label||key,yLabel:`${values[metric][0]}${values[metric][2]?' ('+values[metric][2]+')':''}`};}
 return {metrics,chart,method,notes,table:{headers:['Quantity','Value','Unit'],rows:metrics.map(m=>[m.label,m.value,m.unit])}};
 }};
 expandedTools.push(t);return t;
}
// MATHEMATICS — numerical and geometrical relationships
add('quadratic-roots','Quadratic Equation Discriminant','math','mathematics','Compute real roots of ax²+bx+c=0 and the vertex.',[n('a','Quadratic coefficient a',1),n('b','Linear coefficient b',-3),n('c','Constant c',2)],v=>{valid(v.a!==0,'Coefficient a must not be zero.');const d=v.b*v.b-4*v.a*v.c;valid(d>=0,'Real-root calculator: the discriminant is negative; roots are complex.');return [output('Discriminant',d),output('Root 1',(-v.b+sqrt(d))/(2*v.a)),output('Root 2',(-v.b-sqrt(d))/(2*v.a)),output('Vertex x',-v.b/(2*v.a))]}, {method:'D = b² − 4ac; real roots = (−b ± √D)/(2a). Complex roots are not shown.'});
add('triangle-area','Triangle Area (Heron)','math','mathematics','Calculate triangle area from three side lengths.',[n('a','Side a',3,'m'),n('b','Side b',4,'m'),n('c','Side c',5,'m')],v=>{const {a,b,c}=v;valid(Math.min(a,b,c)>0&&a+b>c&&a+c>b&&b+c>a,'All sides must be positive and satisfy the triangle inequality.');const s=(a+b+c)/2;return [output('Area',sqrt(s*(s-a)*(s-b)*(s-c)),'m²'),output('Perimeter',2*s,'m'),output('Semiperimeter',s,'m')]},{method:'Heron’s formula A = √(s(s−a)(s−b)(s−c)), where s = (a+b+c)/2.'});
add('circle-geometry','Circle Geometry','math','mathematics','Calculate the circumference and area of a circle.',[n('r','Radius',3,'m')],v=>{valid(v.r>0,'Radius must be positive.');return [output('Circumference',2*PI*v.r,'m'),output('Area',PI*v.r*v.r,'m²'),output('Diameter',2*v.r,'m')]},{sweep:{key:'r'},method:'C = 2πr and A = πr².'});
add('sphere-geometry','Sphere Geometry','math','mathematics','Compute volume, diameter, and surface area of a sphere.',[n('r','Radius',2,'m')],v=>{valid(v.r>0,'Radius must be positive.');return [output('Volume',4/3*PI*v.r**3,'m³'),output('Surface area',4*PI*v.r**2,'m²'),output('Diameter',2*v.r,'m')]},{sweep:{key:'r'},method:'V = 4πr³/3; A = 4πr².'});
add('coordinate-distance','2D Distance & Midpoint','math','mathematics','Find distance and midpoint between two Cartesian points.',[n('x1','Point A x',1),n('y1','Point A y',2),n('x2','Point B x',7),n('y2','Point B y',10)],v=>[output('Distance',Math.hypot(v.x2-v.x1,v.y2-v.y1)),output('Midpoint x',(v.x1+v.x2)/2),output('Midpoint y',(v.y1+v.y2)/2)],{method:'Distance = √((x₂−x₁)²+(y₂−y₁)²); midpoint = ((x₁+x₂)/2, (y₁+y₂)/2).'});
add('polar-converter','Polar to Cartesian Coordinates','math','mathematics','Convert polar coordinates to x and y Cartesian coordinates.',[n('r','Radial distance r',5),n('angle','Angle θ',30,'degrees')],v=>[output('X coordinate',v.r*Math.cos(v.angle*PI/180)),output('Y coordinate',v.r*Math.sin(v.angle*PI/180))],{sweep:{key:'angle',from:0,to:360},method:'x = r cos θ, y = r sin θ (θ entered in degrees).'});
add('arithmetic-progression','Arithmetic Sequence Calculator','math','mathematics','Find the nth term and sum of an arithmetic progression.',[n('first','First term',3),n('diff','Common difference',2),n('count','Number of terms',10)],v=>{valid(Number.isInteger(v.count)&&v.count>0&&v.count<=1e7,'Number of terms must be a positive integer ≤10 million.');return [output('Nth term',v.first+(v.count-1)*v.diff),output('Sum of n terms',v.count*(2*v.first+(v.count-1)*v.diff)/2)]},{method:'aₙ = a₁+(n−1)d; Sₙ = n(2a₁+(n−1)d)/2.',sweep:{key:'count',from:1,to:40}});
add('geometric-progression','Geometric Sequence Calculator','math','mathematics','Calculate nth term and finite geometric series sum.',[n('first','First term',2),n('ratio','Common ratio',1.2),n('count','Number of terms',8)],v=>{valid(Number.isInteger(v.count)&&v.count>0&&v.count<=500,'n must be a positive integer ≤500.');return [output('Nth term',v.first*v.ratio**(v.count-1)),output('Finite sum',v.ratio===1?v.first*v.count:v.first*(1-v.ratio**v.count)/(1-v.ratio))]},{method:'aₙ = a₁r^(n−1); Sₙ = a₁(1−rⁿ)/(1−r), or a₁n for r=1.'});
add('pyramid-volume','Rectangular Pyramid Volume','math','mathematics','Calculate volume of a rectangular pyramid.',[n('length','Base length',5,'m'),n('width','Base width',4,'m'),n('height','Height',3,'m')],v=>{valid(v.length>0&&v.width>0&&v.height>0,'All dimensions must be positive.');return [output('Volume',v.length*v.width*v.height/3,'m³'),output('Base area',v.length*v.width,'m²')]},{method:'V = base area × perpendicular height / 3.'});
add('trapezoid-area','Trapezoid Area','math','mathematics','Compute area of a trapezoid from parallel sides and perpendicular height.',[n('a','Parallel side a',8,'m'),n('b','Parallel side b',5,'m'),n('height','Height',4,'m')],v=>{valid(v.a>0&&v.b>0&&v.height>0,'Dimensions must be positive.');return [output('Area',(v.a+v.b)*v.height/2,'m²')]},{method:'A = (a+b)h/2.'});
add('slope-intercept','Two-Point Line Calculator','math','mathematics','Find slope and intercept of a line through two points.',[n('x1','First x',1),n('y1','First y',2),n('x2','Second x',3),n('y2','Second y',8)],v=>{valid(v.x2!==v.x1,'Vertical line has undefined slope and no finite y intercept.');const s=(v.y2-v.y1)/(v.x2-v.x1);return [output('Slope',s),output('Y intercept',v.y1-s*v.x1)]},{method:'Slope m=(y₂−y₁)/(x₂−x₁); b=y₁−mx₁.'});
add('percent-change','Percentage Change Calculator','math','mathematics','Measure absolute and percentage change between two measurements.',[n('initial','Initial value',120),n('final','Final value',150)],v=>{valid(v.initial!==0,'Initial value cannot be zero when calculating percentage change.');return [output('Absolute change',v.final-v.initial),output('Percentage change',100*(v.final-v.initial)/abs(v.initial),'%')]},{method:'Percentage change = 100 × (final−initial)/|initial|; sign indicates direction.'});
