add('z-score','Z-Score Calculator','data','statistics-probability','Standardize a measurement using population mean and standard deviation.',[n('x','Observed value',75),n('mu','Population mean',60),n('sigma','Population SD',10)],v=>{valid(v.sigma>0,'SD must be strictly positive.');return [output('Z-score',(v.x-v.mu)/v.sigma),output('Lower-tail normal probability',cdf((v.x-v.mu)/v.sigma))]},{method:'z = (x−μ)/σ; probability is standard normal CDF Φ(z).',sweep:{key:'x',from:20,to:100}});
add('standard-error','Standard Error of the Mean','data','statistics-probability','Calculate uncertainty of a sample mean from sample SD and sample size.',[n('sd','Sample standard deviation',12),n('count','Sample size n',64)],v=>{valid(v.sd>=0&&Number.isInteger(v.count)&&v.count>=2,'SD must be nonnegative and n must be an integer ≥2.');return [output('Standard error',v.sd/sqrt(v.count)),output('Variance of sample mean',v.sd*v.sd/v.count)]},{method:'SEM = s/√n. Assumes independent observations with finite variance.',sweep:{key:'count',from:2,to:150}});
add('normal-density','Normal Distribution PDF','data','statistics-probability','Compute the probability density of a normal random variable.',[n('x','Evaluation point x',1),n('mu','Mean μ',0),n('sigma','Standard deviation σ',2)],v=>{valid(v.sigma>0,'Standard deviation must be positive.');const z=(v.x-v.mu)/v.sigma;return [output('Probability density',exp(-z*z/2)/(v.sigma*sqrt(2*PI))),output('Z-score',z),output('P(X ≤ x)',cdf(z))]},{sweep:{key:'x',from:-8,to:8},method:'Normal PDF f(x)=exp(−(x−μ)²/(2σ²))/(σ√(2π)). Density is not a point probability.'});
add('binomial-probability','Binomial Probability Calculator','data','statistics-probability','Calculate P(X=k) for a binomial model with n independent Bernoulli trials.',[n('count','Number of trials n',10),n('success','Number of successes k',3),n('prob','Success probability p',0.4)],v=>{valid(Number.isInteger(v.count)&&v.count>=0&&v.count<=1000&&Number.isInteger(v.success)&&v.success>=0&&v.success<=v.count&&v.prob>=0&&v.prob<=1,'Use integers with 0 ≤ k ≤ n ≤1000 and probability from 0 to 1.');const {count:n,success:k,prob:p}=v;const val=p===0?(k===0?1:0):p===1?(k===n?1:0):exp(logFact(n)-logFact(k)-logFact(n-k)+k*ln(p)+(n-k)*ln(1-p));return [output('P(X = k)',val),output('Expected successes',n*p),output('Variance',n*p*(1-p))]},{method:'P(X=k)=C(n,k)p^k(1−p)^(n−k); computed using log-factorials for stability.'});
add('poisson-probability','Poisson Event Probability','data','statistics-probability','Calculate the probability of k events from a Poisson process.',[n('lambda','Expected event count λ',3),n('k','Observed events k',2)],v=>{valid(v.lambda>=0&&Number.isInteger(v.k)&&v.k>=0&&v.k<=1000,'Use λ≥0 and integer k from 0 to 1000.');return [output('P(X = k)',v.lambda===0?(v.k===0?1:0):exp(-v.lambda+v.k*ln(v.lambda)-logFact(v.k))),output('Mean',v.lambda),output('Variance',v.lambda)]},{method:'P(X=k)=e^(−λ)λ^k/k!, assuming a constant independent event rate.'});
add('normal-confidence','Normal Approximation Confidence Interval','data','statistics-probability','Compute a two-sided normal 95% confidence interval for a mean.',[n('mean','Sample mean',45),n('sd','Sample SD',8),n('count','Sample size',64)],v=>{valid(v.sd>=0&&Number.isInteger(v.count)&&v.count>=2,'n must be integer ≥2 and SD nonnegative.');const margin=1.95996398454*v.sd/sqrt(v.count);return [output('Lower limit',v.mean-margin),output('Upper limit',v.mean+margin),output('Margin of error',margin)]},{method:'Approximate 95% CI: x̄ ± 1.95996 × s/√n. For small samples, use a Student-t method instead.'});
add('coefficient-variation','Coefficient of Variation','data','statistics-probability','Calculate relative dispersion from mean and standard deviation.',[n('mean','Arithmetic mean',50),n('sd','Standard deviation',6)],v=>{valid(v.mean!==0&&v.sd>=0,'Mean must be nonzero and SD nonnegative.');return [output('Coefficient of variation',100*v.sd/abs(v.mean),'%'),output('Variance',v.sd*v.sd)]},{method:'CV = 100 × SD/|mean|. Interpretation is unsuitable for some signed or near-zero-mean variables.'});
add('bayes-theorem','Bayes Theorem Calculator','data','statistics-probability','Calculate posterior probability from prior, sensitivity and false-positive rate.',[n('prior','Prior P(H)',.1),n('sensitivity','Likelihood P(+|H)',.9),n('false','False positive P(+|not H)',.1)],v=>{valid(['prior','sensitivity','false'].every(k=>v[k]>=0&&v[k]<=1),'All probabilities must be between 0 and 1.');const d=v.sensitivity*v.prior+v.false*(1-v.prior);valid(d>0,'Conditioning event has zero probability.');return [output('Posterior P(H|+)',v.sensitivity*v.prior/d),output('P(positive)',d)]},{method:'P(H|+) = P(+|H)P(H) / [P(+|H)P(H)+P(+|¬H)P(¬H)].',sweep:{key:'prior',from:0,to:1}});
add('sample-size-proportion','Proportion Sample Size (Approximate)','data','statistics-probability','Estimate sample size for a two-sided 95% proportion interval.',[n('p','Expected population proportion',.5),n('margin','Margin of error',.05)],v=>{valid(v.p>0&&v.p<1&&v.margin>0&&v.margin<1,'Use 0 < p < 1 and 0 < error < 1.');const n=1.95996398454**2*v.p*(1-v.p)/v.margin**2;return [output('Minimum sample size',Math.ceil(n),'people'),output('Unrounded sample size',n)]},{method:'n≈z²p(1−p)/E² for independent simple random samples from a large population; no design effects.'});
add('pearson-correlation','Pearson Correlation Calculator','data','statistics-probability','Calculate Pearson r and covariance from paired numerical measurements.',[txt('data','Paired x y measurements','1 2\n2 4\n3 5\n4 8\n5 10')],v=>{const p=pairs(v.data);valid(p.length>=2,'At least two pairs required.');const x=p.map(q=>q.x),y=p.map(q=>q.y),mx=mean(x),my=mean(y);const cov=mean(p.map(q=>(q.x-mx)*(q.y-my))),sx=sqrt(mean(x.map(a=>(a-mx)**2))),sy=sqrt(mean(y.map(a=>(a-my)**2)));valid(sx>0&&sy>0,'Both variables must vary.');return [output('Pearson correlation r',cov/(sx*sy)),output('Sample covariance',cov*p.length/(p.length-1)),output('Paired observations',p.length)]},{method:'r = Σ[(x−x̄)(y−ȳ)]/√(Σ(x−x̄)² Σ(y−ȳ)²). Correlation does not establish causation.'});
add('expected-value','Discrete Expected Value','data','statistics-probability','Compute expectation and variance from values and corresponding probabilities.',[txt('values','Outcomes (comma-separated)','1, 2, 3, 4'),txt('probs','Probabilities','0.1, 0.2, 0.3, 0.4')],v=>{const xs=nums(v.values),ps=nums(v.probs);valid(xs.length===ps.length&&ps.every(p=>p>=0)&&abs(ps.reduce((s,p)=>s+p,0)-1)<1e-7,'Outcomes/probabilities must match; probabilities must be nonnegative and sum to 1.');const m=xs.reduce((s,x,i)=>s+x*ps[i],0);return [output('Expected value',m),output('Variance',xs.reduce((s,x,i)=>s+(x-m)**2*ps[i],0))]},{method:'E[X]=Σxᵢpᵢ and Var(X)=Σpᵢ(xᵢ−E[X])².'});
