add('debroglie-wavelength','de Broglie Wavelength','physics','physics','Calculate matter-wave wavelength for nonrelativistic momentum.',[n('mass','Particle mass',9.1093837139e-31,'kg'),n('speed','Particle speed',1e6,'m/s')],v=>{valid(v.mass>0&&v.speed>0&&v.speed<.1*299792458,'Require positive mass and speed below 0.1c for nonrelativistic approximation.');return [output('de Broglie wavelength',6.62607015e-34/(v.mass*v.speed),'m'),output('Momentum',v.mass*v.speed,'kg·m/s')]},{sweep:{key:'speed',from:1e5,to:2e6},method:'λ=h/p≈h/(mv) for nonrelativistic velocities.'});
add('radioactive-half-life','Radioactive Decay','physics','physics','Calculate remaining fraction of a radioactive sample.',[n('initial','Initial sample quantity',100,'g'),n('half','Half-life',5,'years'),n('elapsed','Elapsed time',12,'years')],v=>{valid(v.initial>=0&&v.half>0&&v.elapsed>=0,'Initial amount and elapsed time nonnegative; half-life positive.');return [output('Remaining quantity',v.initial*2**(-v.elapsed/v.half),'g'),output('Fraction remaining',2**(-v.elapsed/v.half)),output('Decay constant',ln(2)/v.half,'year⁻¹')]},{sweep:{key:'elapsed',from:0,to:35},method:'N(t)=N₀2^(−t/t½). Assumes constant decay probability.'});
add('snell-refraction','Snell Refraction','physics','physics','Calculate the transmitted angle of light between two uniform media.',[n('n1','Refractive index 1',1),n('n2','Refractive index 2',1.5),n('incident','Incident angle',30,'degrees')],v=>{valid(v.n1>0&&v.n2>0&&v.incident>=0&&v.incident<90,'Indices must be positive; incident angle from 0 to below 90°.');const s=v.n1*Math.sin(v.incident*PI/180)/v.n2;valid(abs(s)<=1,'Total internal reflection: no real refraction angle.');return [output('Refraction angle',Math.asin(s)*180/PI,'degrees'),output('sin(theta2)',s)]},{sweep:{key:'incident',from:0,to:80},method:'n₁ sinθ₁ = n₂ sinθ₂, angles measured from surface normal.'});
add('thin-lens','Thin Lens Equation','physics','physics','Compute image location and magnification for a thin lens.',[n('f','Focal length',0.2,'m'),n('object','Object distance',0.5,'m')],v=>{valid(v.f!==0&&v.object!==0&&abs(1/v.f-1/v.object)>1e-14,'Focal/object distances cannot be zero; image at infinity for object in focal plane.');const d=1/(1/v.f-1/v.object);return [output('Image distance',d,'m'),output('Lateral magnification',-d/v.object)]},{method:'1/f=1/u+1/v, m=−v/u. Sign convention: positive real-object and converging-lens focal lengths.'});
add('wave-frequency','Wave Speed, Frequency & Wavelength','physics','physics','Calculate frequency and period of a wave from speed and wavelength.',[n('speed','Phase speed',340,'m/s'),n('lambda','Wavelength',1.7,'m')],v=>{valid(v.speed>0&&v.lambda>0,'Speed and wavelength positive.');const f=v.speed/v.lambda;return [output('Frequency',f,'Hz'),output('Period',1/f,'s')]},{sweep:{key:'lambda',from:.2,to:5},method:'v=fλ and T=1/f for a periodic wave.'});
add('simple-harmonic','Mass–Spring Oscillation','physics','physics','Calculate frequency and period for an ideal mass-spring oscillator.',[n('mass','Oscillating mass',.5,'kg'),n('spring','Spring stiffness',200,'N/m')],v=>{valid(v.mass>0&&v.spring>0,'Mass and stiffness positive.');const omega=sqrt(v.spring/v.mass);return [output('Angular frequency',omega,'rad/s'),output('Frequency',omega/(2*PI),'Hz'),output('Period',2*PI/omega,'s')]},{sweep:{key:'mass',from:.1,to:2},method:'ω=√(k/m), T=2π√(m/k). Undamped, linear motion.'});
// CHEMISTRY
add('mole-mass','Mole and Mass Converter','chemistry','chemistry','Convert sample mass to amount of substance using molar mass.',[n('mass','Sample mass',18,'g'),n('molar','Molar mass',18.015,'g/mol')],v=>{valid(v.mass>=0&&v.molar>0,'Mass nonnegative and molar mass positive.');return [output('Amount of substance',v.mass/v.molar,'mol'),output('Particle count',v.mass/v.molar*6.02214076e23,'entities')]},{sweep:{key:'mass',from:0,to:90},method:'n=m/M and number of entities = n×N_A, N_A=6.02214076×10²³ mol⁻¹.'});
add('molarity','Solution Molarity Calculator','chemistry','chemistry','Calculate concentration from solute moles and total solution volume.',[n('moles','Solute quantity',.25,'mol'),n('volume','Solution volume',.5,'L')],v=>{valid(v.moles>=0&&v.volume>0,'Moles nonnegative and volume positive.');return [output('Molar concentration',v.moles/v.volume,'mol/L'),output('Concentration',1000*v.moles/v.volume,'mmol/L')]},{sweep:{key:'moles',from:0,to:1},method:'C=n/V, where V is the final solution volume.'});
add('solution-dilution','Solution Dilution Calculator','chemistry','chemistry','Calculate volume of stock solution needed for an ideal dilution.',[n('c1','Stock concentration',2,'mol/L'),n('c2','Target concentration',.5,'mol/L'),n('v2','Target volume',200,'mL')],v=>{valid(v.c1>0&&v.c2>=0&&v.c2<=v.c1&&v.v2>0,'Stock concentration must be positive and at least the target concentration; volume positive.');return [output('Stock volume required',v.c2*v.v2/v.c1,'mL'),output('Additional solvent (ideal)',v.v2*(1-v.c2/v.c1),'mL')]},{method:'C₁V₁=C₂V₂. Solvent volume estimate assumes additive solution volumes.'});
add('strong-acid-ph','Strong Acid pH','chemistry','chemistry','Estimate pH of a dilute monoprotic strong acid with water autoionization.',[n('concentration','Acid concentration',.001,'mol/L'),n('pkw','pKw',14)],v=>{valid(v.concentration>=0&&v.pkw>0&&v.pkw<30,'Concentration nonnegative; pKw from 0 to 30.');const kw=10**(-v.pkw),h=(v.concentration+sqrt(v.concentration**2+4*kw))/2;return [output('pH',-Math.log10(h)),output('Hydrogen ion concentration',h,'mol/L')]},{sweep:{key:'concentration',from:0,to:.1},method:'[H⁺] = (C+√(C²+4Kw))/2; pH=−log₁₀[H⁺], assuming ideal activity.'});
add('ideal-gas-chem','Ideal Gas Law','chemistry','chemistry','Compute pressure of an ideal gas from temperature, moles, and volume.',[n('moles','Amount of gas',1,'mol'),n('temperature','Temperature',298.15,'K'),n('volume','Volume',.024,'m³')],v=>{valid(v.moles>=0&&v.temperature>0&&v.volume>0,'Moles ≥0, Kelvin temperature and volume >0.');return [output('Pressure',v.moles*8.314462618*v.temperature/v.volume,'Pa'),output('Pressure',v.moles*8.314462618*v.temperature/v.volume/101325,'atm')]},{sweep:{key:'temperature',from:200,to:500},method:'PV=nRT with R=8.314462618 J/(mol·K). Ideal, single-phase model.'});
add('arrhenius','Arrhenius Temperature Dependence','chemistry','chemical-engineering','Estimate the ratio of rate constants at two absolute temperatures.',[n('ea','Activation energy',60000,'J/mol'),n('t1','Initial temperature',290,'K'),n('t2','New temperature',320,'K')],v=>{valid(v.ea>=0&&v.t1>0&&v.t2>0,'Energy nonnegative and temperatures in Kelvin >0.');return [output('Rate constant ratio k2/k1',exp(-v.ea/8.314462618*(1/v.t2-1/v.t1)))]},{sweep:{key:'t2',from:280,to:360},method:'ln(k₂/k₁)=−Ea/R(1/T₂−1/T₁), treating Ea as constant.'});
add('reaction-yield','Chemical Reaction Percent Yield','chemistry','chemistry','Calculate percentage yield using actual and theoretical product masses.',[n('actual','Actual product mass',7.5,'g'),n('theoretical','Theoretical product mass',10,'g')],v=>{valid(v.actual>=0&&v.theoretical>0,'Actual ≥0; theoretical >0.');return [output('Percent yield',100*v.actual/v.theoretical,'%'),output('Mass difference',v.theoretical-v.actual,'g')]},{sweep:{key:'actual',from:0,to:12},method:'Percent yield = 100 × actual mass / theoretical mass. Values above 100% may indicate impurities or measurement error.'});
add('first-order-kinetics','First-Order Chemical Kinetics','chemistry','chemistry','Model first-order concentration decay over time.',[n('initial','Initial concentration',1,'mol/L'),n('k','First-order rate constant',.05,'min⁻¹'),n('elapsed','Time',20,'min')],v=>{valid(v.initial>=0&&v.k>0&&v.elapsed>=0,'Initial concentration and time must be nonnegative and k must be positive.');return [output('Remaining concentration',v.initial*exp(-v.k*v.elapsed),'mol/L'),output('Half-life',v.k>0?ln(2)/v.k:Infinity,'min')]},{sweep:{key:'elapsed',from:0,to:100},method:'C(t)=C₀ exp(−kt) and t½=ln2/k for k>0.'});
add('henderson-hasselbalch','Buffer pH (Henderson–Hasselbalch)','chemistry','chemistry','Estimate pH from acid pKa and conjugate base-to-acid concentration ratio.',[n('pka','Acid pKa',4.76),n('base','Conjugate-base concentration',.2,'mol/L'),n('acid','Weak-acid concentration',.1,'mol/L')],v=>{valid(v.base>0&&v.acid>0,'Acid and base concentrations positive.');return [output('Estimated pH',v.pka+Math.log10(v.base/v.acid)),output('Base-to-acid ratio',v.base/v.acid)]},{sweep:{key:'base',from:.01,to:.5},method:'pH≈pKa+log₁₀([A⁻]/[HA]); valid for an ideal buffer system away from extreme dilution.'});
add('osmotic-pressure','Ideal Osmotic Pressure','chemistry','pharmacy','Compute dilute-solution osmotic pressure.',[n('conc','Molar concentration',.15,'mol/L'),n('factor','Van ’t Hoff factor i',1),n('temp','Temperature',298.15,'K')],v=>{valid(v.conc>=0&&v.factor>0&&v.temp>0,'Concentration ≥0, factor and Kelvin temperature >0.');return [output('Osmotic pressure',v.factor*v.conc*1000*8.314462618*v.temp,'Pa')]},{method:'π=iCRT; mol/L converted to mol/m³. Assumes ideal dilute solution.'});
add('mass-percent','Solution Mass Percentage','chemistry','chemistry','Calculate mass percentage of a solute in solution.',[n('solute','Solute mass',12,'g'),n('total','Total solution mass',150,'g')],v=>{valid(v.solute>=0&&v.total>0&&v.solute<=v.total,'Solute mass must be between 0 and total solution mass.');return [output('Mass percentage',100*v.solute/v.total,'%'),output('Solvent mass',v.total-v.solute,'g')]},{method:'Mass fraction (%) = 100 × solute mass / total solution mass.'});
