add('data-transfer','Data Transfer Time','computing','computer-science','Estimate time to transfer a file at a constant effective data rate.',[n('size','File size',1200,'MB'),n('rate','Effective transfer speed',80,'Mbps')],v=>{valid(v.size>=0&&v.rate>0,'Size nonnegative and effective throughput positive.');return [output('Transfer time',v.size*8/v.rate,'s'),output('Transfer time',v.size*8/v.rate/60,'min')]},{sweep:{key:'size',from:0,to:5000},method:'t = size (decimal MB) × 8 / throughput (decimal Mbps). Assumes no protocol overhead, pauses, or congestion.'});
add('storage-capacity','Binary Storage Capacity','computing','computer-science','Compare decimal gigabytes and binary gibibytes.',[n('gigabytes','Capacity',512,'GB')],v=>{valid(v.gigabytes>=0,'Capacity must be nonnegative.');const b=v.gigabytes*1e9;return [output('Binary capacity',b/2**30,'GiB'),output('Total bytes',b,'bytes')]},{method:'1 GB=10⁹ bytes; 1 GiB=2³⁰ bytes.'});
add('bitrate-audio','Audio PCM File Size','computing','computer-science','Estimate uncompressed pulse-code-modulated audio size.',[n('seconds','Duration',180,'s'),n('sample','Sampling rate',44100,'samples/s'),n('bits','Bit depth',16,'bits'),n('channels','Audio channels',2)],v=>{valid(v.seconds>=0&&v.sample>0&&v.bits>0&&Number.isInteger(v.channels)&&v.channels>0&&v.channels<=64,'Positive sampling parameters; channels integer 1–64.');const b=v.seconds*v.sample*v.bits*v.channels/8;return [output('Raw file size',b/1e6,'MB'),output('Bitrate',v.sample*v.bits*v.channels/1000,'kbps')]},{method:'bytes = duration × sample rate × bit depth × channels / 8; excludes file header and compression.'});
add('image-memory','Raw Image Memory Estimator','computing','computer-science','Estimate uncompressed image memory requirement.',[n('width','Image width',1920,'px'),n('height','Image height',1080,'px'),n('channels','Color channels',4),n('bits','Bits per channel',8)],v=>{valid([v.width,v.height,v.channels,v.bits].every(x=>Number.isInteger(x)&&x>0)&&v.width<=200000&&v.height<=200000,'All quantities must be positive integers, with reasonable dimensions.');return [output('Raw storage',v.width*v.height*v.channels*v.bits/8/2**20,'MiB'),output('Pixel count',v.width*v.height,'pixels')]},{method:'memory = width × height × channels × bits/channel ÷ 8 (uncompressed).'});
add('shannon-entropy','Binary Shannon Entropy','computing','computer-science','Calculate information entropy of a Bernoulli source.',[n('prob','Probability of event',.4)],v=>{valid(v.prob>=0&&v.prob<=1,'Probability must be from 0 to 1.');const h=p=>p===0?0:-p*Math.log2(p);return [output('Information entropy',h(v.prob)+h(1-v.prob),'bits'),output('Complement probability',1-v.prob)]},{sweep:{key:'prob',from:0,to:1},method:'H(p)=−p log₂p−(1−p)log₂(1−p), with 0log0 defined as zero.'});
add('sigmoid-function','Sigmoid Activation Function','computing','computer-science','Compute logistic sigmoid and its gradient for a neural-network input.',[n('x','Input x',1.5)],v=>{const s=1/(1+exp(-v.x));return [output('Sigmoid σ(x)',s),output('Derivative σ′(x)',s*(1-s))]},{sweep:{key:'x',from:-8,to:8},method:'σ(x)=1/(1+e⁻ˣ), σ′(x)=σ(x)(1−σ(x)).'});
add('gradient-descent','Gradient Descent Step','computing','computer-science','Calculate one gradient descent step for a quadratic loss.',[n('x','Current parameter x',5),n('target','Quadratic minimum',2),n('rate','Learning rate',.1)],v=>{valid(v.rate>=0&&v.rate<=10,'Learning rate must be between 0 and 10.');const grad=2*(v.x-v.target),newx=v.x-v.rate*grad;return [output('Gradient at x',grad),output('Updated x',newx),output('New loss',(newx-v.target)**2)]},{method:'Loss L=(x−target)²; x_next=x−α×2(x−target). A single update is not convergence.'});
add('cosine-similarity','2D Cosine Similarity','computing','computer-science','Calculate cosine similarity and Euclidean distance between two vectors.',[n('ax','Vector A x',2),n('ay','Vector A y',3),n('bx','Vector B x',4),n('by','Vector B y',1)],v=>{const na=Math.hypot(v.ax,v.ay),nb=Math.hypot(v.bx,v.by);valid(na>0&&nb>0,'Cosine similarity undefined for zero vectors.');return [output('Cosine similarity',(v.ax*v.bx+v.ay*v.by)/(na*nb)),output('Euclidean distance',Math.hypot(v.ax-v.bx,v.ay-v.by))]},{method:'Cosine = (a·b)/(|a||b|), valid for nonzero vectors; Euclidean distance = |a−b|.'});
add('logarithmic-complexity','Algorithm Growth Comparison','computing','computer-science','Compare logarithmic, linear and quadratic growth at a given input size.',[n('count','Problem size n',1000)],v=>{valid(Number.isInteger(v.count)&&v.count>=1&&v.count<=1e9,'n must be a positive integer ≤1 billion.');return [output('log₂ n',Math.log2(v.count)),output('n',v.count),output('n log₂ n',v.count*Math.log2(v.count)),output('n²',v.count**2)]},{sweep:{key:'count',from:1,to:2000,metric:2},method:'Compare asymptotic growth functions; these are operation-scale proxies, not execution-time predictions.'});
add('compression-ratio','Compression Ratio Calculator','computing','computer-science','Measure storage saved by lossless or lossy compression.',[n('original','Original size',125,'MB'),n('compressed','Compressed size',35,'MB')],v=>{valid(v.original>0&&v.compressed>0,'Sizes must be positive.');return [output('Compression factor',v.original/v.compressed,'×'),output('Space saved',100*(v.original-v.compressed)/v.original,'%')]},{method:'Factor = original/compressed; savings = 100×(1−compressed/original).'});
add('network-latency','Network Round Trip Model','computing','electronics-communication','Estimate physical propagation latency plus a fixed processing delay.',[n('distance','One-way fiber distance',2000,'km'),n('speed','Signal speed in fiber',200000,'km/s'),n('delay','Processing overhead each way',3,'ms')],v=>{valid(v.distance>=0&&v.speed>0&&v.delay>=0,'Distance and processing nonnegative, speed positive.');return [output('Propagation one way',1000*v.distance/v.speed,'ms'),output('Estimated round trip',2000*v.distance/v.speed+2*v.delay,'ms')]},{method:'RTT≈2(distance/signal speed + processing). Ignores routing, queuing, switching and retransmissions.'});
add('shannon-channel','Shannon Channel Capacity','computing','electronics-communication','Estimate theoretical channel capacity from bandwidth and SNR.',[n('bandwidth','Bandwidth',1e6,'Hz'),n('snr','Signal-to-noise ratio',20,'dB')],v=>{valid(v.bandwidth>0,'Bandwidth positive.');return [output('Ideal channel capacity',v.bandwidth*Math.log2(1+10**(v.snr/10)),'bits/s'),output('Linear SNR',10**(v.snr/10))]},{sweep:{key:'snr',from:-10,to:40},method:'C = B log₂(1+SNR_linear), SNR_linear =10^(SNR_dB/10). Shannon bound, not achieved throughput.'});
