add('bacterial-growth','Exponential Bacterial Growth','biology','biological-sciences','Compute idealized population growth from doubling time.',[n('initial','Initial population',1000,'cells'),n('doubling','Doubling time',30,'min'),n('elapsed','Elapsed time',120,'min')],v=>{valid(v.initial>=0&&v.doubling>0&&v.elapsed>=0,'Nonnegative population/time and positive doubling time.');return [output('Estimated population',v.initial*2**(v.elapsed/v.doubling),'cells'),output('Growth multiplier',2**(v.elapsed/v.doubling))]},{sweep:{key:'elapsed',from:0,to:180},method:'N(t)=N₀×2^(t/t_d). Real cultures have nutrient and density limits.'});
add('logistic-population','Logistic Population Growth','biology','biological-sciences','Model constrained population growth with carrying capacity.',[n('initial','Initial population',80),n('capacity','Carrying capacity',2000),n('rate','Intrinsic rate r',.3,'year⁻¹'),n('elapsed','Elapsed time',10,'years')],v=>{valid(v.initial>0&&v.capacity>0&&v.rate>=0&&v.elapsed>=0,'Population and capacity positive; r and time nonnegative.');return [output('Population at t',v.capacity/(1+(v.capacity/v.initial-1)*exp(-v.rate*v.elapsed))),output('Carrying capacity',v.capacity)]},{sweep:{key:'elapsed',from:0,to:35},method:'N(t)=K/[1+(K/N₀−1)e^(−rt)]. Fixed K and r; no migration or stochastic effects.'});
add('hardy-weinberg','Hardy–Weinberg Allele Frequencies','biology','biological-sciences','Compute expected genotype proportions from an allele frequency.',[n('p','Allele A frequency p',.6)],v=>{valid(v.p>=0&&v.p<=1,'Frequency must be between 0 and 1.');const q=1-v.p;return [output('AA expected frequency',v.p**2),output('Aa expected frequency',2*v.p*q),output('aa expected frequency',q*q)]},{sweep:{key:'p',from:0,to:1,metric:1},method:'p²+2pq+q²=1 for a random-mating ideal population without selection/migration/mutation.'});
add('michaelis-menten','Michaelis–Menten Enzyme Rate','biology','biological-sciences','Calculate initial enzyme velocity from substrate concentration.',[n('vmax','Maximum rate',10,'µmol/min'),n('km','Michaelis constant Km',2,'mM'),n('substrate','Substrate concentration',4,'mM')],v=>{valid(v.vmax>0&&v.km>0&&v.substrate>=0,'Vmax and Km positive, substrate ≥0.');return [output('Reaction rate',v.vmax*v.substrate/(v.km+v.substrate),'µmol/min'),output('V/Vmax',v.substrate/(v.km+v.substrate))]},{sweep:{key:'substrate',from:0,to:25},method:'v=Vmax×[S]/(Km+[S]); single substrate and steady-state assumptions.'});
add('dna-gc-content','DNA GC Content','biology','biological-sciences','Calculate GC fraction and base counts for a DNA sequence.',[txt('sequence','DNA sequence (A, T, G, C)','ATGCGGATCGTTAGCA')],v=>{const seq=v.sequence.toUpperCase().replace(/\s/g,'');valid(seq.length>0&&seq.length<=100000&&/^[ACGT]+$/.test(seq),'Provide 1–100,000 DNA bases containing only A, C, G, T.');const gc=(seq.match(/[GC]/g)||[]).length;return [output('GC content',100*gc/seq.length,'%'),output('Sequence length',seq.length,'bp'),output('AT bases',seq.length-gc,'bases')]},{method:'GC%=100×(count G + count C)/sequence length. Ambiguous nucleotide symbols must be resolved before analysis.'});
add('dilution-factor','Laboratory Dilution Factor','biology','biological-sciences','Calculate dilution factor from aliquot and final volume.',[n('aliquot','Aliquot volume',2,'mL'),n('final','Final volume',50,'mL')],v=>{valid(v.aliquot>0&&v.final>=v.aliquot,'Final volume must be at least the positive aliquot volume.');return [output('Dilution factor',v.final/v.aliquot,'×'),output('Sample fraction',v.aliquot/v.final)]},{method:'DF=V_final/V_aliquot. Assumes homogeneous solution and additive volumes.'});
add('cfu-count','Colony Forming Unit Estimate','biology','biological-sciences','Estimate CFU concentration from plate colony count and plated volume.',[n('colonies','Counted colonies',120),n('dilution','Dilution factor (e.g. 1000)',1000),n('volume','Plated volume',.1,'mL')],v=>{valid(Number.isInteger(v.colonies)&&v.colonies>=0&&v.dilution>=1&&v.volume>0,'Colony count must be an integer ≥0; factor ≥1 and plated volume >0.');return [output('Estimated concentration',v.colonies*v.dilution/v.volume,'CFU/mL')]},{method:'CFU/mL=colonies × reciprocal dilution factor / plated volume (mL). Valid colony-count range depends on protocol.'});
add('simpson-diversity','Simpson Biodiversity Index','biology','biological-sciences','Compute Simpson’s diversity index from species abundances.',[txt('counts','Counts by species','10, 15, 6, 9')],v=>{const a=nums(v.counts);valid(a.length>=2&&a.every(x=>Number.isInteger(x)&&x>=0),'Enter nonnegative integer counts for at least two species.');const N=a.reduce((s,x)=>s+x,0);valid(N>=2,'At least two individuals required.');const D=a.reduce((s,x)=>s+x*(x-1),0)/(N*(N-1));return [output('Simpson diversity (1−D)',1-D),output('Simpson dominance D',D),output('Total individuals',N)]},{method:'D=Σnᵢ(nᵢ−1)/[N(N−1)], diversity index =1−D.'});
add('ecology-shannon','Ecological Shannon Diversity','biology','biological-sciences','Calculate Shannon entropy of ecological species counts.',[txt('counts','Species counts','20, 15, 8, 7')],v=>{const a=nums(v.counts);valid(a.length>=2&&a.every(x=>Number.isInteger(x)&&x>=0),'Species counts must be nonnegative integers.');const total=a.reduce((s,x)=>s+x,0);valid(total>0,'Total count must exceed zero.');return [output('Shannon diversity H',-a.reduce((s,x)=>s+(x>0?x/total*ln(x/total):0),0),'nats'),output('Total observed',total)]},{method:'H=−Σpᵢ ln pᵢ; natural logarithm; sampling and species classification affect interpretation.'});
add('cell-culture-seeding','Cell Culture Seeding Density','biology','biomedical-engineering','Estimate volume needed to seed a cell culture at a target cell count.',[n('concentration','Cell suspension concentration',1e6,'cells/mL'),n('target','Target number of cells',2e5,'cells')],v=>{valid(v.concentration>0&&v.target>=0,'Concentration positive and target nonnegative.');return [output('Suspension volume',v.target/v.concentration,'mL'),output('Suspension volume',1000*v.target/v.concentration,'µL')]},{method:'V=target cell count / counted cell concentration. Viability and counting error not modeled.'});
add('body-surface-area','Body Surface Area (Mosteller)','health','basic-medical','Compute anthropometric body surface area for classroom study, not clinical decisions.',[n('height','Height',170,'cm'),n('weight','Weight',70,'kg')],v=>{valid(v.height>0&&v.weight>0,'Positive dimensions required.');return [output('Estimated BSA',sqrt(v.height*v.weight/3600),'m²')]},{method:'BSA = √(height[cm]×weight[kg]/3600) m² (Mosteller). Educational estimate only; not for dose calculations or care decisions.',notes:['Not for clinical medication dosing or treatment decisions.','BSA estimates depend on population and formula choice.']});
add('body-mass-index','Body Mass Index (Arithmetic)','health','basic-medical','Compute an anthropometric ratio from measured height and mass.',[n('weight','Body mass',70,'kg'),n('height','Height',1.75,'m')],v=>{valid(v.height>0&&v.weight>0,'Height and mass positive.');return [output('BMI',v.weight/v.height**2,'kg/m²')]},{method:'BMI=mass(kg)/height(m)². A screening ratio, not a diagnosis or complete health assessment.',notes:['BMI is not a standalone diagnostic measure and interpretation differs by population.','Do not make health decisions solely from a numerical calculator.']});
add('epidemiology-prevalence','Disease Prevalence Percentage','health','public-health','Calculate prevalence in a defined population and time frame.',[n('cases','Existing cases',120),n('population','Population',10000)],v=>{valid(Number.isInteger(v.cases)&&Number.isInteger(v.population)&&v.population>0&&v.cases>=0&&v.cases<=v.population,'Use integer cases from 0 to population.');return [output('Prevalence',100*v.cases/v.population,'%'),output('Cases per 1,000',1000*v.cases/v.population)]},{method:'Point prevalence = existing cases / population at a given point in time. Case definitions and population sampling matter.'});
add('epidemiology-incidence','Incidence Rate per Person-Time','health','public-health','Compute an event incidence rate from observed new cases and total person-years.',[n('cases','New cases',25),n('personyears','Observation person-years',2400)],v=>{valid(v.cases>=0&&v.personyears>0&&Number.isInteger(v.cases),'New case count integer ≥0, person-time positive.');return [output('Rate per 1,000 person-years',1000*v.cases/v.personyears),output('Rate per person-year',v.cases/v.personyears)]},{method:'Incidence rate = new events / total person-time. Not the same as cumulative incidence risk.'});
add('relative-risk','Two-Group Relative Risk','health','public-health','Compare event risk in exposed and unexposed groups.',[n('a','Cases in exposed group',30),n('n1','Total exposed group',200),n('c','Cases in control group',15),n('n0','Total control group',200)],v=>{valid(v.n1>0&&v.n0>0&&v.a>=0&&v.c>=0&&v.a<=v.n1&&v.c<=v.n0,'Valid group totals and case counts are required.');valid(v.c>0,'Zero events in control: standard risk ratio undefined.');return [output('Exposed risk',v.a/v.n1),output('Control risk',v.c/v.n0),output('Risk ratio',(v.a/v.n1)/(v.c/v.n0))]},{method:'RR = (events_exposed/total_exposed)/(events_control/total_control). Association is not proof of causation.'});
add('diagnostic-test-metrics','Diagnostic Test Confusion Matrix','health','public-health','Calculate test sensitivity, specificity, and predictive values from counts.',[n('tp','True positives',90),n('fp','False positives',20),n('tn','True negatives',180),n('fn','False negatives',10)],v=>{valid(Object.values(v).every(x=>Number.isInteger(x)&&x>=0),'All counts must be nonnegative integers.');valid(v.tp+v.fn>0&&v.tn+v.fp>0&&v.tp+v.fp>0&&v.tn+v.fn>0,'Denominator group counts must be nonzero.');return [output('Sensitivity',100*v.tp/(v.tp+v.fn),'%'),output('Specificity',100*v.tn/(v.tn+v.fp),'%'),output('Positive predictive value',100*v.tp/(v.tp+v.fp),'%'),output('Negative predictive value',100*v.tn/(v.tn+v.fn),'%')]},{method:'Sensitivity TP/(TP+FN), specificity TN/(TN+FP), PPV TP/(TP+FP), NPV TN/(TN+FN). Predictive values depend on prevalence.'});
add('pharmacokinetic-decay','Drug Concentration Half-Life Model','health','pharmacy','Illustrate first-order pharmacokinetic concentration decline (not dosing advice).',[n('initial','Initial concentration',20,'mg/L'),n('half','Elimination half-life',6,'h'),n('elapsed','Elapsed time',12,'h')],v=>{valid(v.initial>=0&&v.half>0&&v.elapsed>=0,'Initial concentration and time ≥0, half-life positive.');return [output('Modeled concentration',v.initial*2**(-v.elapsed/v.half),'mg/L'),output('Fraction remaining',2**(-v.elapsed/v.half))]},{sweep:{key:'elapsed',from:0,to:36},method:'C(t)=C₀×2^(−t/t½). One-compartment first-order illustrative model only.',notes:['Not suitable for medication scheduling, prescribing, dose changes, or individual patient predictions.','Real elimination can depend on organ function, saturation, metabolism, interactions and dosing history.']});
add('nutrition-macros','Macronutrient Energy Arithmetic','health','food-nutrition','Estimate food energy from listed grams of protein, carbohydrate, and fat.',[n('protein','Protein',20,'g'),n('carb','Carbohydrate',60,'g'),n('fat','Fat',15,'g')],v=>{valid(Object.values(v).every(x=>x>=0),'Macronutrient masses must be nonnegative.');const kcal=4*v.protein+4*v.carb+9*v.fat;return [output('Approximate energy',kcal,'kcal'),output('Energy',kcal*4.184,'kJ')]},{method:'Atwater general factors: protein≈4, carbohydrate≈4, fat≈9 kcal/g. Food labeling may use adjusted factors.'});
// EARTH, SPACE AND ENVIRONMENT
add('astronomy-flux','Astronomical Magnitude Difference','earth','earth-space','Compute flux ratio from a difference in apparent magnitudes.',[n('m1','Apparent magnitude 1',2),n('m2','Apparent magnitude 2',5)],v=>[output('Flux ratio F1/F2',10**(.4*(v.m2-v.m1)))],{sweep:{key:'m2',from:-1,to:10},method:'F₁/F₂=10^(0.4(m₂−m₁)); lower apparent magnitude means brighter object.'});
add('parsec-lightyear','Astronomical Distance Converter','earth','earth-space','Convert parsecs into light-years and astronomical units.',[n('parsecs','Distance',10,'pc')],v=>{valid(v.parsecs>=0,'Distance nonnegative.');return [output('Distance',v.parsecs*3.261563777,'light-years'),output('Distance',v.parsecs*206264.806247,'AU')]},{sweep:{key:'parsecs'},method:'1 parsec≈3.261563777 light-years≈206264.806 AU (IAU-based approximate conversions).'});
add('plate-motion','Tectonic Plate Displacement','earth','earth-space','Estimate accumulated plate displacement from a constant velocity.',[n('speed','Plate velocity',3,'cm/year'),n('years','Elapsed years',1e6,'years')],v=>{valid(v.years>=0,'Elapsed time nonnegative.');return [output('Displacement',v.speed*v.years/100,'m'),output('Displacement',v.speed*v.years/1e5,'km')]},{sweep:{key:'years',from:0,to:5e6},method:'Distance = plate velocity × elapsed time; assumes constant speed and direction.'});
add('atmospheric-pressure','Exponential Atmosphere Pressure','earth','earth-space','Estimate atmospheric pressure in an isothermal hydrostatic atmosphere.',[n('sea','Reference pressure',101325,'Pa'),n('altitude','Altitude difference',1500,'m'),n('scale','Atmospheric scale height',8400,'m')],v=>{valid(v.sea>0&&v.scale>0,'Reference pressure and scale height must be positive.');return [output('Estimated pressure',v.sea*exp(-v.altitude/v.scale),'Pa'),output('Pressure ratio',exp(-v.altitude/v.scale))]},{sweep:{key:'altitude',from:0,to:20000},method:'P(z)=P₀ exp(−z/H) for an isothermal atmosphere with fixed scale height H.'});
add('hydrostatic-ocean','Seawater Hydrostatic Pressure','earth','marine-ocean','Estimate pressure below sea surface using constant seawater density.',[n('density','Seawater density',1025,'kg/m³'),n('depth','Depth',100,'m'),n('surface','Surface absolute pressure',101325,'Pa')],v=>{valid(v.density>0&&v.depth>=0&&v.surface>=0,'Density positive, depth and surface pressure nonnegative.');return [output('Gauge pressure',v.density*9.80665*v.depth,'Pa'),output('Absolute pressure',v.surface+v.density*9.80665*v.depth,'Pa')]},{sweep:{key:'depth',from:0,to:1000},method:'P_abs=P_surface+ρgh, assuming uniform density and constant g.'});
add('ocean-wave-speed','Shallow Water Wave Speed','earth','marine-ocean','Estimate shallow-water gravity-wave propagation speed.',[n('depth','Water depth',10,'m'),n('gravity','Gravitational acceleration',9.81,'m/s²')],v=>{valid(v.depth>0&&v.gravity>0,'Positive depth and gravitational acceleration required.');return [output('Wave speed',sqrt(v.gravity*v.depth),'m/s')]},{sweep:{key:'depth',from:1,to:200},method:'c=√(gh) for wavelength much larger than depth.'});
add('radiocarbon-age','Radiocarbon Age (Simplified)','humanities','archaeology','Estimate radiocarbon age from measured fraction of original carbon-14.',[n('fraction','Remaining carbon-14 fraction',.5),n('half','Assumed half-life',5730,'years')],v=>{valid(v.fraction>0&&v.fraction<=1&&v.half>0,'Remaining fraction in (0,1] and positive half-life.');return [output('Uncalibrated age',-v.half*ln(v.fraction)/ln(2),'years BP')]},{sweep:{key:'fraction',from:.05,to:1},method:'Age=−(half-life/ln2) ln(remaining fraction). Not a calibrated radiocarbon age; real dating requires correction and calibration.'});
// ENGINEERING: mechanical, electrical, civil, aerospace, maritime, textile and process
add('tensile-stress','Axial Tensile Stress','engineering','mechanical-engineering','Compute uniform axial stress from applied force and cross-sectional area.',[n('force','Axial force',15000,'N'),n('area','Area',250,'mm²')],v=>{valid(v.area>0,'Cross-sectional area positive.');return [output('Axial stress',v.force/(v.area*1e-6)/1e6,'MPa')]},{sweep:{key:'force',from:0,to:40000},method:'σ=F/A with area converted from mm² to m²; uniform uniaxial loading.'});
add('axial-strain','Engineering Strain','engineering','mechanical-engineering','Calculate axial strain from extension and initial gauge length.',[n('delta','Change in length',.75,'mm'),n('initial','Original length',100,'mm')],v=>{valid(v.initial>0,'Initial length positive.');return [output('Engineering strain',v.delta/v.initial),output('Microstrain',1e6*v.delta/v.initial,'µε')]},{method:'ε = ΔL/L₀; small deformation engineering strain, not logarithmic true strain.'});
add('youngs-modulus','Young Modulus from Stress and Strain','engineering','mechanical-engineering','Estimate linear elastic modulus from measured stress and axial strain.',[n('stress','Axial stress',100,'MPa'),n('strain','Engineering strain',.0005)],v=>{valid(v.strain!==0,'Strain must be nonzero.');return [output('Estimated modulus',v.stress/v.strain/1000,'GPa')]},{method:'E=σ/ε in the linear elastic region. Requires consistent stress and strain units.'});
add('cantilever-tip','Cantilever Beam Deflection','engineering','civil-engineering','Calculate end deflection of an ideal cantilever carrying a tip point load.',[n('force','Tip force',1000,'N'),n('length','Cantilever span',2,'m'),n('E','Young modulus',200,'GPa'),n('I','Second moment of area',8e-6,'m⁴')],v=>{valid(v.length>0&&v.E>0&&v.I>0,'Span, modulus and area moment must be positive.');return [output('Tip deflection',v.force*v.length**3/(3*v.E*1e9*v.I)*1000,'mm'),output('Fixed-end moment',v.force*v.length,'N·m')]},{sweep:{key:'force',from:0,to:5000},method:'Euler–Bernoulli small-deflection cantilever with tip load δ=FL³/(3EI). Uniform beam, linear elasticity.'});
add('thermal-expansion','Linear Thermal Expansion','engineering','mechanical-engineering','Compute change in bar length for a temperature change.',[n('length','Original length',5,'m'),n('alpha','Expansion coefficient',12e-6,'K⁻¹'),n('delta','Temperature change',40,'K')],v=>{valid(v.length>0&&v.alpha>=0,'Length positive and expansion coefficient nonnegative.');return [output('Change in length',v.length*v.alpha*v.delta,'m'),output('Final length',v.length*(1+v.alpha*v.delta),'m')]},{sweep:{key:'delta',from:-50,to:100},method:'ΔL=αL₀ΔT, for approximately constant linear thermal expansion coefficient.'});
add('reynolds-number','Reynolds Number Calculator','engineering','mechanical-engineering','Estimate Reynolds number for fluid motion through a characteristic length.',[n('density','Fluid density',1000,'kg/m³'),n('velocity','Flow speed',1.5,'m/s'),n('diameter','Characteristic length',.05,'m'),n('viscosity','Dynamic viscosity',.001,'Pa·s')],v=>{valid(v.density>0&&v.velocity>=0&&v.diameter>0&&v.viscosity>0,'Density, length and viscosity positive; velocity nonnegative.');return [output('Reynolds number',v.density*v.velocity*v.diameter/v.viscosity)]},{sweep:{key:'velocity',from:0,to:4},method:'Re=ρVD/μ, using chosen characteristic length; transition thresholds depend on geometry and flow.'});
add('mechanical-power','Rotating Shaft Power','engineering','mechanical-engineering','Calculate mechanical shaft power from torque and rotational speed.',[n('torque','Torque',120,'N·m'),n('rpm','Rotational speed',1800,'rev/min')],v=>{valid(v.rpm>=0,'Rotational speed must be nonnegative.');return [output('Shaft power',v.torque*2*PI*v.rpm/60/1000,'kW'),output('Angular velocity',2*PI*v.rpm/60,'rad/s')]},{sweep:{key:'rpm',from:0,to:3500},method:'P=τω, ω=2πRPM/60; ideal mechanical shaft output.'});
add('ohms-law','Ohm Law & Power','engineering','electrical-engineering','Calculate direct-current resistance, power and conductance.',[n('voltage','Voltage',12,'V'),n('resistance','Resistance',6,'Ω')],v=>{valid(v.resistance>0,'Resistance must be positive.');return [output('Current',v.voltage/v.resistance,'A'),output('Dissipated power',v.voltage**2/v.resistance,'W'),output('Conductance',1/v.resistance,'S')]},{sweep:{key:'voltage',from:0,to:40},method:'I=V/R, P=V²/R, G=1/R for a linear resistor.'});
add('parallel-resistors','Two Resistors: Series & Parallel','engineering','electrical-engineering','Compute equivalent resistance of two ideal resistors.',[n('r1','First resistance',100,'Ω'),n('r2','Second resistance',200,'Ω')],v=>{valid(v.r1>0&&v.r2>0,'Resistances must be positive.');return [output('Series equivalent',v.r1+v.r2,'Ω'),output('Parallel equivalent',v.r1*v.r2/(v.r1+v.r2),'Ω')]},{method:'Series R=R₁+R₂; parallel R=(R₁R₂)/(R₁+R₂).'});
add('rc-circuit','RC Charge & Discharge Model','engineering','electrical-engineering','Estimate charging voltage and discharge voltage in an ideal RC circuit.',[n('R','Resistance',10000,'Ω'),n('C','Capacitance',100,'µF'),n('supply','Source voltage',5,'V'),n('elapsed','Elapsed time',1,'s')],v=>{valid(v.R>0&&v.C>0&&v.elapsed>=0,'R, C positive and elapsed time ≥0.');const tau=v.R*v.C*1e-6;return [output('Time constant',tau,'s'),output('Charging voltage',v.supply*(1-exp(-v.elapsed/tau)),'V'),output('Discharge voltage',v.supply*exp(-v.elapsed/tau),'V')]},{sweep:{key:'elapsed',from:0,to:5,metric:1},method:'V_charge=V_s(1−e^(−t/RC)); V_discharge=V₀e^(−t/RC), with ideal component model.'});
add('inductor-reactance','Inductive Reactance','engineering','electrical-engineering','Calculate reactance magnitude for an inductor at an AC frequency.',[n('freq','Frequency',50,'Hz'),n('L','Inductance',.1,'H')],v=>{valid(v.freq>=0&&v.L>0,'Frequency nonnegative and inductance positive.');return [output('Inductive reactance',2*PI*v.freq*v.L,'Ω')]},{sweep:{key:'freq',from:0,to:1000},method:'X_L=2πfL for sinusoidal steady state.'});
add('capacitor-reactance','Capacitive Reactance','engineering','electrical-engineering','Calculate magnitude of capacitive reactance at an AC frequency.',[n('freq','AC frequency',50,'Hz'),n('C','Capacitance',10,'µF')],v=>{valid(v.freq>0&&v.C>0,'Frequency and capacitance must be positive.');return [output('Capacitive reactance',1/(2*PI*v.freq*v.C*1e-6),'Ω')]},{sweep:{key:'freq',from:5,to:500},method:'|X_C|=1/(2πfC), C in farads.'});
add('transformer-ratio','Ideal Transformer Ratio','engineering','electrical-engineering','Calculate secondary voltage and current in an ideal transformer.',[n('primary','Primary voltage',230,'V'),n('n1','Primary turns',1000),n('n2','Secondary turns',200),n('current','Primary current',2,'A')],v=>{valid(v.n1>0&&v.n2>0,'Winding turns positive.');return [output('Secondary voltage',v.primary*v.n2/v.n1,'V'),output('Secondary current',v.current*v.n1/v.n2,'A')]},{method:'V₂/V₁=N₂/N₁ and I₂/I₁=N₁/N₂, ideal lossless transformer.'});
add('ac-power-factor','Single-Phase AC Real Power','engineering','electrical-engineering','Compute real and apparent power from RMS voltage, current and power factor.',[n('voltage','RMS voltage',230,'V'),n('current','RMS current',6,'A'),n('pf','Power factor',.85)],v=>{valid(v.voltage>=0&&v.current>=0&&v.pf>=-1&&v.pf<=1,'RMS quantities nonnegative and PF in [−1,1].');return [output('Real power',v.voltage*v.current*v.pf,'W'),output('Apparent power',v.voltage*v.current,'VA'),output('Reactive magnitude',v.voltage*v.current*sqrt(1-v.pf**2),'VAR')]},{method:'P=VIcosφ, S=VI, |Q|=VI√(1−PF²). |Q| omits leading/lagging sign.'});
add('concrete-volume','Concrete Slab Volume','engineering','civil-engineering','Estimate geometric concrete volume from length, width and thickness.',[n('length','Slab length',12,'m'),n('width','Slab width',6,'m'),n('thickness','Thickness',.15,'m')],v=>{valid(v.length>0&&v.width>0&&v.thickness>0,'Dimensions must be positive.');return [output('Net volume',v.length*v.width*v.thickness,'m³'),output('Area',v.length*v.width,'m²')]},{sweep:{key:'thickness',from:.05,to:.4},method:'V=L×W×t; construction waste, reinforcement, and excavation are excluded.'});
add('soil-bearing','Foundation Average Bearing Pressure','engineering','civil-engineering','Estimate average contact pressure beneath a rectangular foundation.',[n('load','Vertical foundation load',800,'kN'),n('length','Footing length',3,'m'),n('width','Footing width',2,'m')],v=>{valid(v.load>=0&&v.length>0&&v.width>0,'Load nonnegative and footing dimensions positive.');return [output('Mean contact pressure',v.load/(v.length*v.width),'kPa'),output('Footing area',v.length*v.width,'m²')]},{method:'q=vertical force/footing area. Assumes concentric uniform load; not a bearing-capacity or safety evaluation.'});
add('euler-buckling','Euler Column Buckling Load','engineering','civil-engineering','Calculate ideal elastic critical buckling force for a slender column.',[n('E','Elastic modulus',200,'GPa'),n('I','Minimum second moment',8e-6,'m⁴'),n('L','Unsupported length',3,'m'),n('K','Effective length factor',1)],v=>{valid(v.E>0&&v.I>0&&v.L>0&&v.K>0,'Elastic modulus, I, length and K must be positive.');return [output('Elastic critical load',PI**2*v.E*1e9*v.I/(v.K*v.L)**2/1000,'kN')]},{sweep:{key:'L',from:1,to:6},method:'P_cr=π²EI/(KL)²; only ideal straight slender columns in linear elastic buckling. Not a design certification.'});
add('darcy-flow','Darcy Porous Media Flow','engineering','civil-engineering','Estimate Darcy volumetric flow through a porous cross-section.',[n('conductivity','Hydraulic conductivity',1e-5,'m/s'),n('area','Flow cross-section',5,'m²'),n('gradient','Hydraulic gradient',.03)],v=>{valid(v.conductivity>=0&&v.area>0,'Conductivity ≥0, area >0.');return [output('Discharge rate',v.conductivity*v.area*v.gradient,'m³/s')]},{method:'Q=K A i, where i is the signed hydraulic gradient, within the Darcy flow regime.'});
add('manning-flow','Manning Open Channel Velocity','engineering','civil-engineering','Estimate mean flow velocity from Manning roughness and hydraulic radius.',[n('radius','Hydraulic radius',.6,'m'),n('slope','Energy slope',.002),n('roughness','Manning n',.025)],v=>{valid(v.radius>0&&v.slope>=0&&v.roughness>0,'Hydraulic radius and roughness positive, slope nonnegative.');return [output('Mean velocity',v.radius**(2/3)*sqrt(v.slope)/v.roughness,'m/s')]},{method:'Manning velocity V=(1/n)R_h^(2/3)S^(1/2), SI units, steady uniform open-channel flow.'});
add('lift-force','Aircraft Lift Estimate','engineering','aerospace-engineering','Estimate aerodynamic lift using lift coefficient and dynamic pressure.',[n('density','Air density',1.225,'kg/m³'),n('speed','Airspeed',60,'m/s'),n('area','Wing reference area',16,'m²'),n('cl','Lift coefficient',.8)],v=>{valid(v.density>0&&v.speed>=0&&v.area>0,'Density and area >0; airspeed ≥0.');return [output('Lift force',.5*v.density*v.speed**2*v.area*v.cl,'N')]},{sweep:{key:'speed',from:0,to:150},method:'L=½ρV²S C_L. C_L varies with geometry, angle of attack, Reynolds and Mach number.'});
add('drag-force','Aerodynamic Drag Estimate','engineering','aerospace-engineering','Estimate drag force using air density, reference area and drag coefficient.',[n('density','Fluid density',1.225,'kg/m³'),n('speed','Speed',30,'m/s'),n('area','Reference area',1.5,'m²'),n('cd','Drag coefficient',.4)],v=>{valid(v.density>0&&v.speed>=0&&v.area>0&&v.cd>=0,'Positive density, area; speed and drag coefficient nonnegative.');return [output('Estimated drag',.5*v.density*v.speed**2*v.area*v.cd,'N')]},{sweep:{key:'speed',from:0,to:90},method:'D=½ρV²AC_D with a specified, constant empirical drag coefficient.'});
add('rocket-delta-v','Ideal Rocket Equation','engineering','aerospace-engineering','Calculate ideal velocity change from effective exhaust speed and mass ratio.',[n('exhaust','Effective exhaust velocity',3000,'m/s'),n('initial','Initial mass',20000,'kg'),n('final','Final mass',12000,'kg')],v=>{valid(v.exhaust>0&&v.initial>v.final&&v.final>0,'Initial mass must exceed positive final mass and exhaust speed >0.');return [output('Ideal Δv',v.exhaust*ln(v.initial/v.final),'m/s'),output('Mass ratio',v.initial/v.final)]},{method:'Tsiolkovsky Δv=v_e ln(m_initial/m_final), ignoring gravity and drag losses.'});
add('mach-number','Mach Number Calculator','engineering','aerospace-engineering','Calculate Mach number and ideal-gas speed of sound.',[n('speed','Flight speed',260,'m/s'),n('gamma','Specific-heat ratio',1.4),n('R','Specific gas constant',287,'J/(kg·K)'),n('temp','Absolute temperature',288,'K')],v=>{valid(v.speed>=0&&v.gamma>1&&v.R>0&&v.temp>0,'Speed≥0, gamma>1, gas constant and Kelvin temperature >0.');const a=sqrt(v.gamma*v.R*v.temp);return [output('Mach number',v.speed/a),output('Speed of sound',a,'m/s')]},{sweep:{key:'speed',from:0,to:750},method:'M=V/a, a=√(γRT), ideal gas with constant γ.'});
add('process-residence','Process Tank Residence Time','engineering','chemical-engineering','Calculate nominal residence time of a perfectly mixed flow vessel.',[n('volume','Tank working volume',8,'m³'),n('flow','Volumetric throughflow',2,'m³/h')],v=>{valid(v.volume>0&&v.flow>0,'Volume and flow rate positive.');return [output('Nominal residence time',v.volume/v.flow,'h')]},{method:'τ=V/Q for constant-volume continuous flow; not actual residence-time distribution.'});
add('process-conversion','Single-Pass Reactor Conversion','engineering','chemical-engineering','Calculate reactant fractional conversion from inlet and outlet molar flow.',[n('inlet','Inlet reactant flow',100,'mol/s'),n('outlet','Outlet reactant flow',32,'mol/s')],v=>{valid(v.inlet>0&&v.outlet>=0&&v.outlet<=v.inlet,'Inlet >0, outlet between zero and inlet.');return [output('Conversion',100*(v.inlet-v.outlet)/v.inlet,'%'),output('Reactant consumed',v.inlet-v.outlet,'mol/s')]},{method:'X=(F_A,in−F_A,out)/F_A,in for steady-state reactant flow measurement.'});
add('log-mean-temperature','Log Mean Temperature Difference','engineering','chemical-engineering','Calculate LMTD from positive heat-exchanger terminal temperature differences.',[n('dt1','First terminal temperature difference',60,'K'),n('dt2','Second terminal temperature difference',30,'K')],v=>{valid(v.dt1>0&&v.dt2>0,'Both terminal differences must be strictly positive.');return [output('LMTD',abs(v.dt1-v.dt2)<1e-12?v.dt1:(v.dt1-v.dt2)/ln(v.dt1/v.dt2),'K')]},{method:'LMTD=(ΔT₁−ΔT₂)/ln(ΔT₁/ΔT₂), continuous limit ΔT when equal. Geometry correction factor is not included.'});
add('buoyancy-force','Archimedes Buoyancy','engineering','marine-ocean','Compute ideal buoyant force from displaced liquid volume.',[n('density','Liquid density',1025,'kg/m³'),n('volume','Displaced volume',.8,'m³'),n('gravity','Gravitational acceleration',9.81,'m/s²')],v=>{valid(v.density>0&&v.volume>=0&&v.gravity>0,'Density/gravity positive, displaced volume ≥0.');return [output('Buoyant force',v.density*v.volume*v.gravity,'N')]},{sweep:{key:'volume',from:0,to:3},method:'F_b=ρ_fluid×V_displaced×g, neglecting compressibility and density gradients.'});
add('textile-gsm','Fabric GSM Calculator','engineering','textile-engineering','Calculate fabric mass per square meter from measured sample area.',[n('mass','Fabric sample mass',5,'g'),n('area','Sample area',.02,'m²')],v=>{valid(v.mass>=0&&v.area>0,'Mass nonnegative and area positive.');return [output('Fabric areal mass',v.mass/v.area,'g/m²')]},{method:'GSM = sample mass (g)/sample area (m²). Drying and conditioning affect textile measurement.'});
add('yarn-tex','Yarn Linear Density (Tex)','engineering','textile-engineering','Compute linear mass density of yarn in tex and denier.',[n('mass','Yarn mass',12,'g'),n('length','Yarn length',2000,'m')],v=>{valid(v.mass>=0&&v.length>0,'Mass nonnegative and length positive.');const tex=1000*v.mass/v.length;return [output('Tex',tex,'g/1000m'),output('Denier',9*tex,'g/9000m')]},{method:'tex = 1000×mass(g)/length(m); denier=9×tex.'});
// AGRICULTURE, FOOD & FORESTRY
add('fertilizer-nutrient','Fertilizer Nutrient Mass','agriculture','agricultural-engineering','Calculate supplied nutrient mass from fertilizer mass and concentration.',[n('fertilizer','Applied fertilizer',50,'kg'),n('content','Listed nutrient mass content',46,'%')],v=>{valid(v.fertilizer>=0&&v.content>=0&&v.content<=100,'Mass nonnegative and nutrient content between 0 and 100%.');return [output('Nutrient mass',v.fertilizer*v.content/100,'kg')]},{method:'Nutrient mass = fertilizer mass × labeled mass fraction. Follow agronomic guidance and local regulations for real application.'});
add('irrigation-volume','Irrigation Volume from Water Depth','agriculture','agricultural-engineering','Calculate gross irrigation water volume for a field of known area.',[n('area','Field area',2,'hectares'),n('depth','Net water depth',30,'mm'),n('efficiency','Application efficiency',.8)],v=>{valid(v.area>0&&v.depth>=0&&v.efficiency>0&&v.efficiency<=1,'Area positive, depth ≥0, efficiency in (0,1].');return [output('Gross irrigation volume',v.area*10000*v.depth/1000/v.efficiency,'m³')]},{sweep:{key:'depth',from:0,to:100},method:'Gross volume = area(m²) × irrigation depth(m) / efficiency. Does not recommend crop-specific irrigation.'});
add('seed-rate','Seed Requirement Calculator','agriculture','agriculture-forestry','Estimate seed mass based on sowing rate per hectare.',[n('area','Area',2.5,'hectares'),n('rate','Recommended rate',18,'kg/hectare')],v=>{valid(v.area>=0&&v.rate>=0,'Area and seed rate nonnegative.');return [output('Seed quantity',v.area*v.rate,'kg')]},{sweep:{key:'area',from:0,to:20},method:'Seed mass = field area × locally chosen agronomic sowing rate. Not a recommended rate.'});
add('wood-volume','Timber Log Cylinder Volume','agriculture','agriculture-forestry','Estimate volume of a cylindrical log from length and average diameter.',[n('diameter','Average diameter',.35,'m'),n('length','Log length',4,'m')],v=>{valid(v.diameter>0&&v.length>0,'Diameter and length positive.');return [output('Cylinder volume',PI*(v.diameter/2)**2*v.length,'m³')]},{method:'V=πd²L/4. Assumes circular uniform cross-section; taper and defects excluded.'});
add('feed-conversion','Animal Feed Conversion Ratio','agriculture','veterinary','Compute feed conversion ratio from consumed feed and mass gain.',[n('feed','Consumed feed',180,'kg'),n('gain','Body mass gained',90,'kg')],v=>{valid(v.feed>=0&&v.gain>0,'Consumed feed nonnegative and gained mass positive.');return [output('Feed conversion ratio',v.feed/v.gain,'kg/kg')]},{method:'FCR=feed mass / live weight gain. Interpret by species, life stage, and husbandry conditions.'});
// ECONOMICS, BUSINESS, FINANCE, SOCIAL SCIENCE
add('simple-interest','Simple Interest Calculator','economics','finance-accounting','Calculate simple interest on principal over a specified number of years.',[n('principal','Principal',1000,'currency units'),n('rate','Annual interest rate',5,'%'),n('years','Term',3,'years')],v=>{valid(v.principal>=0&&v.years>=0,'Principal and term nonnegative.');const interest=v.principal*v.rate/100*v.years;return [output('Interest',interest),output('Final amount',v.principal+interest)]},{sweep:{key:'years',from:0,to:15},method:'I=Prt, where annual rate r is entered as percent/100. Excludes taxes, fees, and compounding.'});
add('compound-growth','Compound Annual Growth','economics','finance-accounting','Model compound annual growth or interest without cash flows.',[n('initial','Initial amount',1000),n('rate','Annual rate',6,'%'),n('years','Years',10)],v=>{valid(v.initial>=0&&v.rate>-100&&v.years>=0,'Initial amount ≥0, annual rate above −100%, time ≥0.');const fv=v.initial*(1+v.rate/100)**v.years;return [output('Final amount',fv),output('Gain/loss',fv-v.initial)]},{sweep:{key:'years',from:0,to:25},method:'FV=PV(1+r)^t, assuming constant annual compounding, no additional cash flows.'});
add('break-even-units','Contribution Break-Even Units','economics','business-management','Calculate units needed to cover fixed costs at a constant price and variable cost.',[n('fixed','Fixed costs',25000),n('price','Unit selling price',100),n('variable','Variable cost per unit',40)],v=>{valid(v.fixed>=0&&v.price>v.variable&&v.variable>=0,'Fixed cost nonnegative, price must exceed nonnegative variable cost.');const margin=v.price-v.variable;return [output('Contribution margin/unit',margin),output('Break-even sales units',Math.ceil(v.fixed/margin),'units'),output('Break-even sales revenue',Math.ceil(v.fixed/margin)*v.price)]},{method:'Break-even volume=ceil(fixed costs/(price−variable cost)). Assumes linear cost/revenue, constant price and all units sold.'});
add('profit-margin','Gross & Net Profit Margin','economics','business-management','Calculate gross margin and net profit margin from revenue and expenses.',[n('revenue','Revenue',100000),n('cogs','Cost of goods sold',60000),n('other','Other expenses',20000)],v=>{valid(v.revenue>0&&v.cogs>=0&&v.other>=0,'Revenue positive and expenses nonnegative.');return [output('Gross margin',100*(v.revenue-v.cogs)/v.revenue,'%'),output('Net margin',100*(v.revenue-v.cogs-v.other)/v.revenue,'%'),output('Operating net amount',v.revenue-v.cogs-v.other)]},{method:'Gross margin = (revenue−COGS)/revenue; simple net margin additionally deducts listed other expenses.'});
add('net-present-value','Net Present Value (Three Periods)','economics','finance-accounting','Discount three future cash flows and an initial investment.',[n('initial','Initial cost',5000),n('year1','Cash flow year 1',2000),n('year2','Cash flow year 2',2200),n('year3','Cash flow year 3',2400),n('rate','Discount rate',10,'%')],v=>{valid(v.rate>-100&&v.initial>=0,'Discount rate must exceed −100%; initial cost nonnegative.');const d=1+v.rate/100;return [output('Net present value',-v.initial+v.year1/d+v.year2/d**2+v.year3/d**3)]},{sweep:{key:'rate',from:0,to:30},method:'NPV=−C₀+CF₁/(1+r)+CF₂/(1+r)²+CF₃/(1+r)³. Cash-flow timing is at each year-end.'});
add('cagr','Compound Annual Growth Rate','economics','finance-accounting','Compute annualized growth rate between positive start and end amounts.',[n('start','Beginning value',2000),n('end','Ending value',4000),n('years','Number of years',5)],v=>{valid(v.start>0&&v.end>0&&v.years>0,'Beginning/end values and number of years must be positive.');return [output('CAGR',100*((v.end/v.start)**(1/v.years)-1),'%')]},{method:'CAGR = 100×[(ending/beginning)^(1/years)−1]. Does not describe intervening volatility.'});
add('price-elasticity','Arc Price Elasticity of Demand','economics','economics','Compute midpoint arc elasticity between two price and quantity observations.',[n('p1','Initial price',10),n('p2','New price',12),n('q1','Initial demand quantity',100),n('q2','New demand quantity',85)],v=>{valid(v.p1>0&&v.p2>0&&v.q1>0&&v.q2>0&&v.p2!==v.p1,'Prices/quantities positive and price must change.');const dq=(v.q2-v.q1)/((v.q1+v.q2)/2),dp=(v.p2-v.p1)/((v.p1+v.p2)/2);return [output('Arc demand elasticity',dq/dp),output('Absolute elasticity',abs(dq/dp))]},{method:'Midpoint elasticity = [(Q₂−Q₁)/average Q] / [(P₂−P₁)/average P]. Observational change is not necessarily causal.'});
add('inflation-adjustment','Inflation Price Adjustment','economics','economics','Estimate future nominal price using a constant assumed annual inflation rate.',[n('price','Current price',100),n('rate','Assumed annual inflation',4,'%'),n('years','Elapsed years',5)],v=>{valid(v.price>=0&&v.rate>-100&&v.years>=0,'Price ≥0, inflation above −100%, years ≥0.');return [output('Projected nominal price',v.price*(1+v.rate/100)**v.years),output('Purchasing power factor',1/(1+v.rate/100)**v.years)]},{sweep:{key:'years',from:0,to:20},method:'Projected nominal price = initial×(1+i)^t. This is an assumed-rate scenario, not a forecast.'});
add('loan-monthly','Fixed-Rate Loan Payment','economics','finance-accounting','Calculate an illustrative equal monthly payment for an amortizing loan.',[n('principal','Loan principal',10000),n('rate','Annual nominal rate',7,'%'),n('months','Loan term',36,'months')],v=>{valid(v.principal>=0&&v.rate>=0&&Number.isInteger(v.months)&&v.months>=1&&v.months<=1200,'Principal/rate ≥0 and months integer 1–1200.');const r=v.rate/1200;const payment=r===0?v.principal/v.months:v.principal*r/(1-(1+r)**(-v.months));return [output('Monthly payment',payment),output('Total scheduled payments',payment*v.months),output('Total interest',payment*v.months-v.principal)]},{method:'Standard annuity formula for fixed nominal annual rate/12 and equal end-of-month payments. Excludes fees, defaults, and variable rates.'});
add('return-investment','Return on Investment','economics','business-management','Compute an elementary gross return on an initial capital outlay.',[n('cost','Initial investment',1000),n('ending','Final proceeds/value',1200)],v=>{valid(v.cost>0&&v.ending>=0,'Cost positive and final proceeds nonnegative.');return [output('ROI',100*(v.ending-v.cost)/v.cost,'%'),output('Absolute gain',v.ending-v.cost)]},{method:'ROI=(final proceeds−initial cost)/initial cost×100%. Ignores time, taxes and opportunity cost.'});
add('market-concentration','Herfindahl–Hirschman Index','economics','economics','Calculate market concentration from company market shares.',[txt('shares','Market shares (percentage)','40, 30, 20, 10')],v=>{const a=nums(v.shares);valid(a.length>=2&&a.every(x=>x>=0)&&abs(a.reduce((s,x)=>s+x,0)-100)<1e-5,'Provide at least 2 nonnegative shares summing to 100%.');return [output('HHI (0–10,000)',a.reduce((s,x)=>s+x*x,0)),output('Number of firms',a.length)]},{method:'HHI=Σmarket_share_percent². Market definition is central; numeric concentration alone does not establish legal conclusions.'});
add('psych-reaction','Mean Reaction Time','humanities','psychology','Summarize reaction-time measurements with mean and sample standard deviation.',[txt('data','Reaction times (milliseconds)','240, 280, 260, 300, 245, 255')],v=>{const a=nums(v.data);valid(a.length>=2&&a.every(x=>x>0),'At least two positive reaction times needed.');return [output('Mean reaction time',mean(a),'ms'),output('Sample standard deviation',sqrt(variance(a)),'ms'),output('Trials',a.length)]},{method:'Arithmetic mean and sample SD of entered independent trial timings. Quality depends on measurement procedure.'});
// LOGIC, SYSTEMS SCIENCE, HISTORY
add('littles-law','Little Law Queueing Estimate','systems','logic-systems','Estimate average work-in-progress from throughput and elapsed system time.',[n('throughput','Average completed items',12,'items/hour'),n('time','Average system time',.5,'hours')],v=>{valid(v.throughput>=0&&v.time>=0,'Throughput and time nonnegative.');return [output('Average items in system',v.throughput*v.time,'items')]},{sweep:{key:'throughput',from:0,to:40},method:'L=λW for a stable stationary queueing system with consistent flow boundaries.'});
add('boolean-truth','Boolean Logic Truth Table','systems','logic-systems','Generate truth-table counts and example logic outputs for two binary inputs.',[n('a','Boolean A (0 or 1)',1),n('b','Boolean B (0 or 1)',0)],v=>{valid([v.a,v.b].every(x=>x===0||x===1),'Boolean inputs must be 0 or 1.');return [output('A AND B',v.a&v.b),output('A OR B',v.a|v.b),output('A XOR B',v.a^v.b),output('NOT A',1-v.a)]},{method:'Classical two-valued Boolean logic. Values 0=false and 1=true.'});
add('historical-span','Chronological Year Span','humanities','history','Compute elapsed years between two Common Era dates (CE-only).',[n('start','Start year (CE)',1850),n('end','End year (CE)',2026)],v=>{valid(Number.isInteger(v.start)&&Number.isInteger(v.end)&&v.start>=1&&v.end>=v.start,'Enter CE years (integers ≥1) and end year not before start.');return [output('Elapsed years',v.end-v.start,'years'),output('Decades', (v.end-v.start)/10)]},{method:'Calendar year subtraction for Common Era dates only; exact dates and partial years are not modeled.'});
add('sociology-rate','Survey Response Rate','humanities','sociology','Compute valid survey completion and nonresponse rates.',[n('invited','People invited',500),n('responded','Completed surveys',280)],v=>{valid(Number.isInteger(v.invited)&&Number.isInteger(v.responded)&&v.invited>0&&v.responded>=0&&v.responded<=v.invited,'Provide integer invitation count >0 and completed count between 0 and invited.');return [output('Completion rate',100*v.responded/v.invited,'%'),output('Nonresponse rate',100*(v.invited-v.responded)/v.invited,'%')]},{method:'Response = completed valid questionnaires / invitations×100%. Survey sampling and nonresponse bias are separate issues.'});
